-- +goose Up
-- SQLite schema, written to port to PostgreSQL: uuid text ids generated by the
-- app, UTC timestamps written by the app (never SQL defaults, so every value
-- has the same format), no arrays or JSON types. The driver trims trailing
-- zeros from fractional seconds, so timestamps do not compare correctly as
-- text: queries compare them through julianday().
-- Tables are prefixed config_/audit_ where PostgreSQL will use schemas.

CREATE TABLE config_users (
    id            TEXT PRIMARY KEY,
    username      TEXT NOT NULL UNIQUE,
    display_name  TEXT NOT NULL DEFAULT '',
    email         TEXT NOT NULL DEFAULT '',
    password_hash TEXT,                        -- NULL for users of external identity providers
    totp_sealed   BLOB,                        -- vault.Seal(secret, aad = user id)
    totp_enabled  BOOLEAN NOT NULL DEFAULT 0,
    source        TEXT NOT NULL DEFAULT 'local' CHECK (source IN ('local', 'oidc')),
    role          TEXT NOT NULL DEFAULT 'user' CHECK (role IN ('superadmin', 'admin', 'auditor', 'user')),
    disabled      BOOLEAN NOT NULL DEFAULT 0,
    created_at    DATETIME NOT NULL,
    updated_at    DATETIME NOT NULL,
    last_login_at DATETIME
);

CREATE TABLE config_groups (
    id          TEXT PRIMARY KEY,
    name        TEXT NOT NULL UNIQUE,
    description TEXT NOT NULL DEFAULT '',
    source      TEXT NOT NULL DEFAULT 'local' CHECK (source IN ('local', 'oidc')),
    created_at  DATETIME NOT NULL
);

CREATE TABLE config_group_members (
    group_id TEXT NOT NULL REFERENCES config_groups (id) ON DELETE CASCADE,
    user_id  TEXT NOT NULL REFERENCES config_users (id) ON DELETE CASCADE,
    PRIMARY KEY (group_id, user_id)
);
CREATE INDEX config_group_members_user ON config_group_members (user_id);

CREATE TABLE config_folders (
    id         TEXT PRIMARY KEY,
    parent_id  TEXT REFERENCES config_folders (id) ON DELETE RESTRICT,
    name       TEXT NOT NULL,
    created_at DATETIME NOT NULL
);
-- Sibling names are unique; root folders (NULL parent) included.
CREATE UNIQUE INDEX config_folders_sibling_name ON config_folders (coalesce(parent_id, ''), name);

-- How hosts are reached: directly from paltad, or through edge agents.
CREATE TABLE config_sites (
    id               TEXT PRIMARY KEY,
    name             TEXT NOT NULL UNIQUE,
    kind             TEXT NOT NULL CHECK (kind IN ('direct', 'agent')),
    description      TEXT NOT NULL DEFAULT '',
    agent_token_hash TEXT UNIQUE,              -- sha256 hex; agent sites only
    created_at       DATETIME NOT NULL,
    CHECK ((kind = 'agent') = (agent_token_hash IS NOT NULL))
);

CREATE TABLE config_secrets (
    id         TEXT PRIMARY KEY,
    name       TEXT NOT NULL UNIQUE,
    kind       TEXT NOT NULL CHECK (kind IN ('password', 'private_key')),
    username   TEXT NOT NULL,
    sealed     BLOB NOT NULL,                  -- vault.Seal(secret, aad = secret id)
    created_at DATETIME NOT NULL,
    updated_at DATETIME NOT NULL
);

CREATE TABLE config_connections (
    id              TEXT PRIMARY KEY,
    name            TEXT NOT NULL UNIQUE,
    protocol        TEXT NOT NULL CHECK (protocol IN ('ssh', 'rdp', 'vnc')),
    host            TEXT NOT NULL,
    port            INTEGER NOT NULL CHECK (port BETWEEN 1 AND 65535),
    folder_id       TEXT REFERENCES config_folders (id) ON DELETE SET NULL,
    site_id         TEXT REFERENCES config_sites (id) ON DELETE RESTRICT,
    environment     TEXT NOT NULL DEFAULT '',
    description     TEXT NOT NULL DEFAULT '',
    backend         TEXT NOT NULL DEFAULT 'paltad' CHECK (backend IN ('paltad', 'guacd')),
    credential_mode TEXT NOT NULL DEFAULT 'vault' CHECK (credential_mode IN ('vault', 'prompt')),
    secret_id       TEXT REFERENCES config_secrets (id) ON DELETE SET NULL,
    params          TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(params)),  -- protocol-specific
    record          BOOLEAN NOT NULL DEFAULT 1,
    record_input    BOOLEAN NOT NULL DEFAULT 0,
    host_key        TEXT,
    created_at      DATETIME NOT NULL,
    updated_at      DATETIME NOT NULL
);
CREATE INDEX config_connections_folder ON config_connections (folder_id);

CREATE TABLE config_connection_tags (
    connection_id TEXT NOT NULL REFERENCES config_connections (id) ON DELETE CASCADE,
    tag           TEXT NOT NULL,
    PRIMARY KEY (connection_id, tag)
);
CREATE INDEX config_connection_tags_tag ON config_connection_tags (tag);

-- Grants: a subject (user or group) may act on an object (one connection, a
-- folder subtree, or every connection carrying a tag). expires_at = JIT.
CREATE TABLE config_policies (
    id                  TEXT PRIMARY KEY,
    subject_type        TEXT NOT NULL CHECK (subject_type IN ('user', 'group')),
    subject_id          TEXT NOT NULL,
    object_type         TEXT NOT NULL CHECK (object_type IN ('connection', 'folder', 'tag')),
    object_ref          TEXT NOT NULL,         -- id for connection/folder, tag name for tag
    can_connect         BOOLEAN NOT NULL DEFAULT 1,
    can_view_recordings BOOLEAN NOT NULL DEFAULT 0,
    expires_at          DATETIME,
    description         TEXT NOT NULL DEFAULT '',
    created_by          TEXT,
    created_at          DATETIME NOT NULL
);
CREATE INDEX config_policies_subject ON config_policies (subject_type, subject_id);
CREATE INDEX config_policies_object ON config_policies (object_type, object_ref);

CREATE TABLE config_web_sessions (
    id_hash      TEXT PRIMARY KEY,             -- sha256 hex of the cookie value
    user_id      TEXT NOT NULL REFERENCES config_users (id) ON DELETE CASCADE,
    mfa_pending  BOOLEAN NOT NULL DEFAULT 0,
    ip           TEXT NOT NULL DEFAULT '',
    user_agent   TEXT NOT NULL DEFAULT '',
    created_at   DATETIME NOT NULL,
    last_seen_at DATETIME NOT NULL,
    expires_at   DATETIME NOT NULL
);
CREATE INDEX config_web_sessions_user ON config_web_sessions (user_id);

-- Append-only, hash-chained: hash = sha256(prev_hash || canonical event).
CREATE TABLE audit_events (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    ts          DATETIME NOT NULL,
    actor_id    TEXT,
    actor_name  TEXT NOT NULL DEFAULT '',
    actor_ip    TEXT NOT NULL DEFAULT '',
    action      TEXT NOT NULL,
    object_type TEXT NOT NULL DEFAULT '',
    object_id   TEXT NOT NULL DEFAULT '',
    details     TEXT NOT NULL DEFAULT '{}',
    prev_hash   TEXT NOT NULL,
    hash        TEXT NOT NULL UNIQUE
);
CREATE INDEX audit_events_ts ON audit_events (ts);
CREATE INDEX audit_events_object ON audit_events (object_type, object_id);

CREATE TABLE audit_sessions (
    id                  TEXT PRIMARY KEY,
    user_id             TEXT,
    username            TEXT NOT NULL,
    connection_id       TEXT NOT NULL,
    connection_snapshot TEXT NOT NULL,         -- JSON: the connection as it was at start
    site                TEXT NOT NULL DEFAULT '',
    client_ip           TEXT NOT NULL DEFAULT '',
    reason              TEXT NOT NULL DEFAULT '',
    recording           TEXT,
    started_at          DATETIME NOT NULL,
    ended_at            DATETIME,
    end_reason          TEXT
);
CREATE INDEX audit_sessions_started ON audit_sessions (started_at);
CREATE INDEX audit_sessions_user ON audit_sessions (user_id);

-- +goose StatementBegin
CREATE TRIGGER audit_events_no_update BEFORE UPDATE ON audit_events
BEGIN SELECT RAISE(ABORT, 'audit_events is append-only'); END;
-- +goose StatementEnd
-- +goose StatementBegin
CREATE TRIGGER audit_events_no_delete BEFORE DELETE ON audit_events
BEGIN SELECT RAISE(ABORT, 'audit_events is append-only'); END;
-- +goose StatementEnd
-- +goose StatementBegin
CREATE TRIGGER audit_sessions_no_delete BEFORE DELETE ON audit_sessions
BEGIN SELECT RAISE(ABORT, 'audit_sessions is append-only'); END;
-- +goose StatementEnd
-- A session may be updated once, to close it; nothing else may change.
-- +goose StatementBegin
CREATE TRIGGER audit_sessions_close_only BEFORE UPDATE ON audit_sessions
WHEN OLD.ended_at IS NOT NULL
  OR NEW.id IS NOT OLD.id OR NEW.user_id IS NOT OLD.user_id OR NEW.username IS NOT OLD.username
  OR NEW.connection_id IS NOT OLD.connection_id OR NEW.connection_snapshot IS NOT OLD.connection_snapshot
  OR NEW.site IS NOT OLD.site OR NEW.client_ip IS NOT OLD.client_ip OR NEW.reason IS NOT OLD.reason
  OR NEW.recording IS NOT OLD.recording OR NEW.started_at IS NOT OLD.started_at
BEGIN SELECT RAISE(ABORT, 'audit_sessions only allows closing an open session'); END;
-- +goose StatementEnd

-- +goose Down
DROP TABLE audit_sessions;
DROP TABLE audit_events;
DROP TABLE config_web_sessions;
DROP TABLE config_policies;
DROP TABLE config_connection_tags;
DROP TABLE config_connections;
DROP TABLE config_secrets;
DROP TABLE config_sites;
DROP TABLE config_folders;
DROP TABLE config_group_members;
DROP TABLE config_groups;
DROP TABLE config_users;
